import java.util.*; import java.io.*; public class Main { public static long gcd(long a, long b) { while (b != 0) { a %= b; long temp = a; a = b; b = temp; } return a; } public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int T = Integer.parseInt(st.nextToken()); while (T-- > 0) { int N = Integer.parseInt(br.readLine()); long[] A = new long[N]; st = new StringTokenizer(br.readLine()); for (int i = 0; i < N; i++) { A[i] = Long.parseLong(st.nextToken()); } if (N < 2) { System.out.println(0); continue; } long commonDiff = A[1] - A[0]; for (int i = 2; i < N; i++) { commonDiff = gcd(commonDiff, A[i] - A[i - 1]); } if (commonDiff == 0) { System.out.println(0); } else { long targetLength = (A[N - 1] - A[0]) / commonDiff + 1; System.out.println(targetLength - N); } } } }